from __future__ import annotations
import argparse, json
from datetime import datetime
from html import escape
from pathlib import Path
from typing import Any

try:
    from . import performance_store_v26 as store
    from . import performance_registry_v27 as registry
except ImportError:
    import performance_store_v26 as store  # type: ignore
    import performance_registry_v27 as registry  # type: ignore

ROOT=Path(__file__).resolve().parents[1]
DEFAULT_DB=ROOT/"database/ad_performance.sqlite"
DEFAULT_OUT=ROOT/"outputs"/"performance_dashboard_v27.html"

def load_rows(db_path: str|Path=DEFAULT_DB)->list[dict[str,Any]]:
    c=store.connect(db_path);registry.ensure_registry(c);rows=[dict(r) for r in c.execute("SELECT * FROM performance_events ORDER BY observed_at, performance_id")];c.close();return rows

def _sum(rows,key):return sum(float(r.get(key,0) or 0) for r in rows)
def kpis(rows):
    imp=_sum(rows,"impressions");clicks=_sum(rows,"clicks");detail=_sum(rows,"detail_views");p=_sum(rows,"purchases");rev=_sum(rows,"revenue");sp=_sum(rows,"spend")
    return {"impressions":int(imp),"retention_2s":_sum(rows,"views_2s")/imp if imp else 0,"retention_3s":_sum(rows,"views_3s")/imp if imp else 0,"ctr":clicks/imp if imp else 0,"detail_view_rate":detail/imp if imp else 0,"purchase_cvr":p/clicks if clicks else 0,"purchases":int(p),"revenue":rev,"spend":sp,"roas":rev/sp if sp else 0,"cpa":sp/p if p else 0}
def group(rows,key):
    groups={}
    for r in rows:groups.setdefault(str(r.get(key) or "(미지정)"),[]).append(r)
    return [{"name":k,**kpis(v)} for k,v in groups.items()]
def build_summary(rows):return {"generated_at":datetime.now().isoformat(timespec="seconds"),"rows":len(rows),"overall":kpis(rows),"by_platform":group(rows,"platform"),"by_product":group(rows,"product"),"by_category":group(rows,"category"),"by_angle":group(rows,"angle"),"by_hook":group(rows,"hook_text"),"by_creative":group(rows,"creative_id")}

def render_html(rows:list[dict[str,Any]],summary:dict[str,Any])->str:
    data=json.dumps(rows,ensure_ascii=False).replace("</","<\\/");generated=escape(summary["generated_at"])
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V2.7 광고 성과 대시보드</title><style>
:root{{--bg:#0b1020;--panel:#131a2b;--muted:#8ea0bd;--text:#edf3ff;--line:#26324a;--good:#47d18c}}*{{box-sizing:border-box}}body{{margin:0;font-family:Arial,"Noto Sans KR",sans-serif;background:var(--bg);color:var(--text)}}.wrap{{max-width:1600px;margin:auto;padding:22px}}h1{{margin:0 0 6px;font-size:28px}}.sub{{color:var(--muted);margin-bottom:18px}}.filters,.cards,.grid{{display:grid;gap:12px}}.filters{{grid-template-columns:repeat(4,minmax(160px,1fr));margin-bottom:16px}}select{{background:var(--panel);color:var(--text);border:1px solid var(--line);padding:10px;border-radius:10px}}.cards{{grid-template-columns:repeat(5,1fr);margin-bottom:16px}}.card,.panel{{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px}}.card .label{{font-size:12px;color:var(--muted)}}.card .value{{font-size:25px;font-weight:700;margin-top:5px}}.grid{{grid-template-columns:1fr 1fr;margin-bottom:16px}}h2{{font-size:17px;margin:0 0 10px}}table{{width:100%;border-collapse:collapse;font-size:13px}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:right;vertical-align:top}}th:first-child,td:first-child{{text-align:left;max-width:360px;word-break:break-word}}th{{color:var(--muted);position:sticky;top:0;background:var(--panel)}}.scroll{{max-height:430px;overflow:auto}}.barrow{{display:grid;grid-template-columns:190px 1fr 80px;gap:9px;align-items:center;margin:8px 0}}.bar{{height:12px;background:#202b43;border-radius:9px;overflow:hidden}}.fill{{height:100%;background:var(--good);border-radius:9px}}.note{{font-size:12px;color:var(--muted)}}@media(max-width:900px){{.cards{{grid-template-columns:repeat(2,1fr)}}.filters,.grid{{grid-template-columns:1fr}}}}</style></head><body><div class="wrap"><h1>V2.7 광고 성과 대시보드</h1><div class="sub">생성: {generated} · 로컬 단일 HTML · 외부 차트 라이브러리 없음</div><div class="filters"><select id="platform"><option value="">전체 플랫폼</option></select><select id="product"><option value="">전체 상품</option></select><select id="category"><option value="">전체 카테고리</option></select><select id="angle"><option value="">전체 Angle</option></select></div><div class="cards" id="cards"></div><div class="grid"><div class="panel"><h2>플랫폼별 ROAS</h2><div id="platformBars"></div></div><div class="panel"><h2>Angle별 CTR</h2><div id="angleBars"></div></div></div><div class="grid"><div class="panel"><h2>Angle별 CTR · CVR · ROAS</h2><div class="scroll"><table id="angleTable"></table></div></div><div class="panel"><h2>Hook별 CTR · CVR · ROAS</h2><div class="scroll"><table id="hookTable"></table></div></div></div><div class="grid"><div class="panel"><h2>상품별 성과</h2><div class="scroll"><table id="productTable"></table></div></div><div class="panel"><h2>Creative별 성과</h2><div class="scroll"><table id="creativeTable"></table></div></div></div><div class="panel"><h2>운영 해석</h2><div class="note">ROAS만 보지 말고 2초/3초 유지율 → CTR → 상세페이지 유입 → 구매전환을 순서대로 확인하세요. Hook/Creative의 노출이 적으면 성급하게 승패를 확정하지 마세요.</div></div></div><script>const RAW={data};const N=x=>Number(x||0),pct=x=>(x*100).toFixed(2)+'%',won=x=>Math.round(x).toLocaleString('ko-KR')+'원',num=x=>Math.round(x).toLocaleString('ko-KR');function options(id,key){{const s=document.getElementById(id),vals=[...new Set(RAW.map(r=>r[key]||'(미지정)'))].sort();vals.forEach(v=>{{let o=document.createElement('option');o.value=v;o.textContent=v;s.appendChild(o)}});s.onchange=render}}function filtered(){{return RAW.filter(r=>(!platform.value||r.platform===platform.value)&&(!product.value||r.product===product.value)&&(!category.value||r.category===category.value)&&(!angle.value||r.angle===angle.value))}}function agg(rows){{let a={{impressions:0,views_2s:0,views_3s:0,clicks:0,detail_views:0,purchases:0,revenue:0,spend:0}};rows.forEach(r=>Object.keys(a).forEach(k=>a[k]+=N(r[k])));a.ret2=a.impressions?a.views_2s/a.impressions:0;a.ret3=a.impressions?a.views_3s/a.impressions:0;a.ctr=a.impressions?a.clicks/a.impressions:0;a.detail=a.impressions?a.detail_views/a.impressions:0;a.cvr=a.clicks?a.purchases/a.clicks:0;a.roas=a.spend?a.revenue/a.spend:0;a.cpa=a.purchases?a.spend/a.purchases:0;return a}}function groups(rows,key){{let m={{}};rows.forEach(r=>(m[r[key]||'(미지정)']??=[]).push(r));return Object.entries(m).map(([name,x])=>({{name,...agg(x)}}))}}function cards(a){{let arr=[['노출',num(a.impressions)],['2초 유지율',pct(a.ret2)],['3초 유지율',pct(a.ret3)],['CTR',pct(a.ctr)],['상세 유입률',pct(a.detail)],['구매전환율',pct(a.cvr)],['구매',num(a.purchases)],['매출',won(a.revenue)],['광고비',won(a.spend)],['ROAS',a.roas.toFixed(2)+'x']];document.getElementById('cards').innerHTML=arr.map(x=>`<div class="card"><div class="label">${{x[0]}}</div><div class="value">${{x[1]}}</div></div>`).join('')}}function bars(id,arr,metric,fmt){{arr=arr.sort((a,b)=>b[metric]-a[metric]).slice(0,10);let max=Math.max(...arr.map(x=>x[metric]),.0001);document.getElementById(id).innerHTML=arr.map(x=>`<div class="barrow"><div title="${{x.name}}">${{x.name.slice(0,27)}}</div><div class="bar"><div class="fill" style="width:${{Math.max(2,x[metric]/max*100)}}%"></div></div><div>${{fmt(x[metric])}}</div></div>`).join('')||'<div class="note">데이터 없음</div>'}}function table(id,arr){{arr=arr.sort((a,b)=>b.roas-a.roas);document.getElementById(id).innerHTML='<tr><th>이름</th><th>노출</th><th>2초</th><th>CTR</th><th>상세</th><th>CVR</th><th>구매</th><th>ROAS</th></tr>'+arr.map(x=>`<tr><td>${{x.name}}</td><td>${{num(x.impressions)}}</td><td>${{pct(x.ret2)}}</td><td>${{pct(x.ctr)}}</td><td>${{pct(x.detail)}}</td><td>${{pct(x.cvr)}}</td><td>${{num(x.purchases)}}</td><td>${{x.roas.toFixed(2)}}x</td></tr>`).join('')}}function render(){{let r=filtered(),a=agg(r);cards(a);bars('platformBars',groups(r,'platform'),'roas',x=>x.toFixed(2)+'x');bars('angleBars',groups(r,'angle'),'ctr',pct);table('angleTable',groups(r,'angle'));table('hookTable',groups(r,'hook_text'));table('productTable',groups(r,'product'));table('creativeTable',groups(r,'creative_id'))}}['platform','product','category','angle'].forEach(x=>options(x,x));render();</script></body></html>'''

def generate(db_path: str|Path=DEFAULT_DB,out: str|Path=DEFAULT_OUT)->dict[str,Any]:
    rows=load_rows(db_path);summary=build_summary(rows);p=Path(out);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(render_html(rows,summary),encoding="utf-8");jp=p.with_suffix('.json');jp.write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding="utf-8");return {"html":str(p),"summary_json":str(jp),"rows":len(rows),"overall":summary["overall"]}
def parse_args():
    p=argparse.ArgumentParser(description="V2.7 standalone performance dashboard");p.add_argument("--db",default=str(DEFAULT_DB));p.add_argument("--out",default=str(DEFAULT_OUT));return p.parse_args()
def main():
    a=parse_args();print(json.dumps(generate(a.db,a.out),ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
